// Solo números autorizados pueden hablar con el Director
const AUTORIZADOS = ['2222934153'];
const b = $input.first().json.body || {};
const from = b.From || '';
const digits = from.replace(/\D/g, '');
const permitido = AUTORIZADOS.some(n => digits.endsWith(n));
const nm = parseInt(b.NumMedia || '0', 10);
let texto = (b.Body || '').trim();
if (!texto && nm > 0) texto = '[Martín envió un archivo/audio que no puedes ver. Pídele que lo escriba.]';

// Calendario calculado por el sistema (el agente NO debe calcular días de la semana)
const hoy = $now.setZone('America/Mexico_City').startOf('day');
const nombre = d => d.setLocale('es').toFormat("cccc d 'de' LLLL yyyy");
const dias = [];
for (let i = 0; i <= 21; i++) { const d = hoy.minus({ days: i }); dias.push(`${d.toISODate()} = ${nombre(d)}${i===0?' (HOY)':i===1?' (AYER)':''}${d.weekday===7?' — domingo, CERRADO':''}`); }
let ult = hoy.minus({ days: 1 }); if (ult.weekday === 7) ult = ult.minus({ days: 1 });
const ultimoDiaHabil = `${ult.toISODate()} (${nombre(ult)})`;
const mismoDiaSemPasada = `${ult.minus({ days: 7 }).toISODate()} (${nombre(ult.minus({ days: 7 }))})`;
return [{ json: { from, permitido, texto: texto || '(mensaje vacío)', calendario: dias.join('\n'), ultimoDiaHabil, mismoDiaSemPasada } }];

const t = ($input.first().json.output || 'No pude generar respuesta.').trim();
const to = $('Validar remitente').first().json.from;
const partes = []; let resto = t;
while (resto.length > 1500) { let i = resto.lastIndexOf('\n', 1500); if (i < 500) i = 1500; partes.push(resto.slice(0, i)); resto = resto.slice(i).trim(); }
partes.push(resto);
return partes.map(p => ({ json: { to, body: p } }));
